/**
 * Icônes GeniusFiles — géométrie Phosphor figée localement.
 *
 * Le paquet complet embarquait les six graisses de chaque icône (~580 Ko de
 * JavaScript au démarrage). Seules les graisses réellement utilisées sont
 * conservées ici, sous forme de tracés statiques : dessin STRICTEMENT
 * identique, coût de démarrage divisé par dix.
 *
 * Fichier généré — ne pas modifier à la main.
 */
import type { ReactElement, SVGProps } from "react";

export type PhIconProps = Omit<SVGProps<SVGSVGElement>, "children"> & {
  size?: number | string;
  weight?: "bold" | "fill";
};

function make(bold: string, fill?: string) {
  const Icon = ({
    size = 24,
    weight = "bold",
    color,
    ...rest
  }: PhIconProps & { color?: string }): ReactElement => (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 256 256"
      fill={color ?? "currentColor"}
      aria-hidden="true"
      focusable="false"
      {...rest}
      dangerouslySetInnerHTML={{ __html: weight === "fill" && fill ? fill : bold }}
    />
  );
  return Icon;
}

